// Microsoft.Extensions.Resilience (Polly v8) - one pipeline per dependency
builder.Services.AddResilienceHandler("payments", pipeline =>
{
    // 1) Tight timeout per attempt - no timeout, no retry semantics
    pipeline.AddTimeout(TimeSpan.FromMilliseconds(800));

    // 2) Retry only transient outcomes, with backoff + jitter
    pipeline.AddRetry(new RetryStrategyOptions
    {
        MaxRetryAttempts = 3,
        Delay = TimeSpan.FromMilliseconds(100),
        BackoffType = DelayBackoffType.Exponential,
        UseJitter = true,
        ShouldHandle = new PredicateBuilder()
            .Handle<HttpRequestException>()
            .HandleResult(r => (int)r.StatusCode is >= 500 or 429)
    });

    // 3) Circuit breaker: stop hammering a dead dependency
    pipeline.AddCircuitBreaker(new CircuitBreakerStrategyOptions
    {
        SamplingDuration = TimeSpan.FromSeconds(10),
        FailureRatio = 0.5,
        MinimumThroughput = 20,
        BreakDuration = TimeSpan.FromSeconds(30)
    });
});

